import { useId, type CSSProperties } from 'react';

const LOW_END = 500,
  MID_TIER = 2000,
  HIGH_END = 5000;

class LRUCache<T> {
  #capacity: number;
  #cache = new Map<string, T>();

  constructor() {
    if ('deviceMemory' in navigator) {
      const memory = navigator.deviceMemory as number;
      this.#capacity = memory >= 8 ? HIGH_END : memory >= 4 ? MID_TIER : LOW_END;
    } else if ('hardwareConcurrency' in navigator) {
      const cores = navigator.hardwareConcurrency;
      this.#capacity = cores >= 8 ? HIGH_END : cores >= 4 ? MID_TIER : LOW_END;
    } else this.#capacity = LOW_END;
  }

  get(key: string): T | null {
    if (!this.#cache.has(key)) return null;

    const value = this.#cache.get(key)!;
    this.#cache.delete(key);
    this.#cache.set(key, value);
    return value;
  }

  set(key: string, value: T) {
    if (this.#cache.has(key)) this.#cache.delete(key);
    else if (this.#cache.size >= this.#capacity) this.#cache.delete(this.#cache.keys().next().value!);
    this.#cache.set(key, value);
  }

  getOrCompute(key: string, compute: () => T): T {
    let value = this.get(key);
    if (value !== null) return value;

    value = compute();
    this.set(key, value);
    return value;
  }
}

const styleCache = new LRUCache<{ '--radius': string; '--radius-alt': string }>();

export function useCachedStyles(percentageRadius = false): CSSProperties {
  const id = useId();
  return styleCache.getOrCompute(id, () => {
    if (percentageRadius) {
      const r = Array.from({ length: 16 }).map(() => Math.floor(Math.random() * 30 + 35));
      return {
        '--radius': `${r[0]}% ${r[1]}% ${r[2]}% ${r[3]}% / ${r[4]}% ${r[5]}% ${r[6]}% ${r[7]}%`,
        '--radius-alt': `${r[8]}% ${r[9]}% ${r[10]}% ${r[11]}% / ${r[12]}% ${r[13]}% ${r[14]}% ${r[15]}%`,
      };
    }

    const b = Array.from({ length: 8 }).map(() => Math.floor(Math.random() * 250 + 50)),
      s = Array.from({ length: 8 }).map(() => Math.floor(Math.random() * 15 + 5));
    let r1 = `${b[0]}px ${s[0]}px ${b[1]}px ${s[1]}px / ${s[2]}px ${b[2]}px ${s[3]}px ${b[3]}px`,
      r2 = `${s[4]}px ${b[4]}px ${s[5]}px ${b[5]}px / ${b[6]}px ${s[6]}px ${b[7]}px ${s[7]}px`;
    if (Math.random() > 0.5) {
      [r1, r2] = [r2, r1];
    }
    return { '--radius': r1, '--radius-alt': r2, rotate: `${Math.random() - 0.5}deg` };
  }) as CSSProperties;
}
